9	/**
10	 * Emits an audit record for a successfully created owner to the dedicated {@code AUDIT}
11	 * logger, carrying the persisted owner id, its {@code customerCode}, its
12	 * {@code registrationDate}, its {@code membershipLevel} and its {@code membershipNumber}.
13	 * Runs after {@link SaveOwner}
14	 * (so the generated id exists) and before {@link RespondWithOwnerCreated} responds.
15	 */
16	public class AuditOwnerCreated {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    public void service(@Val Owner owner) {
21	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
22	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
23	                owner.getMembershipLevel(), owner.getMembershipNumber());
24	    }
25	}
