61	    @NotEmpty
62	    private String city;
63	
64	    @Column(name = "telephone")
65	    @NotEmpty
66	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
67	    private String telephone;
68	
69	    @Column(name = "email")
70	    private String email;
71	
72	    @Column(name = "postcode")
73	    private String postcode;
74	
75	    @Column(name = "registration_date")
76	    private LocalDate registrationDate;
77	
78	    @Column(name = "birth_date")
79	    private LocalDate birthDate;
80	
81	    @Column(name = "customer_code")
82	    private String customerCode;
83	
84	    @Column(name = "household_id")
85	    private String householdId;
86	
87	    @Column(name = "namesake_count")
88	    private Integer namesakeCount;
89	
90	    @Column(name = "household_size")
91	    private Integer householdSize;
92	
93	    @Column(name = "membership_number")
94	    private String membershipNumber;
95	
96	    @Column(name = "membership_level_cap")
97	    private Integer membershipLevelCap;
98	
99	    @Column(name = "bulk_signup_warning", nullable = false)
100	    private boolean bulkSignupWarning;
101	
102	    @Column(name = "possible_duplicate", nullable = false)
103	    private boolean possibleDuplicate;
104	
105	    @Column(name = "possible_duplicate_of")
106	    private Integer possibleDuplicateOf;
107	
108	    @Column(name = "deleted", nullable = false)
109	    private boolean deleted;
110	
111	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
112	    private Set<Pet> pets;
113	
114	    /**
115	     * The owner's personal title (one of MR, MRS, MS or DR), or null when none was
116	     * supplied. Stored verbatim and used to compose the {@link #getSalutation() salutation}.
117	     */
118	    public String getTitle() {
119	        return this.title;
120	    }
121	
122	    public void setTitle(String title) {
123	        this.title = title;
124	    }
125	
126	    /**
127	     * The owner's salutation: the {@link #getTitle() title} and last name separated by a
128	     * space (e.g. {@code "DR Who"}), or just the last name when no title is recorded.
129	     * Derived from stored state, never persisted.
130	     */
131	    public String getSalutation() {
132	        return (this.title == null || this.title.isEmpty())
133	            ? getLastName()
134	            : this.title + " " + getLastName();
135	    }
136	
137	    public String getAddress() {
138	        return this.address;
139	    }
140	
141	    public void setAddress(String address) {
142	        this.address = address;
143	    }
144	
145	    /**
146	     * The first line of the owner's structured address, in normalized form, or null when the
147	     * owner was created from the flat {@link #getAddress() address} only. The composed
148	     * {@code address} is derived from this and {@link #getAddressLine2()}.
149	     */
150	    public String getAddressLine1() {
151	        return this.addressLine1;
152	    }
153	
154	    public void setAddressLine1(String addressLine1) {
155	        this.addressLine1 = addressLine1;
156	    }
157	
158	    /**
159	     * The optional second line of the owner's structured address, in normalized form, or null
160	     * when absent or when the owner was created from the flat {@link #getAddress() address}.
161	     */
162	    public String getAddressLine2() {
163	        return this.addressLine2;
164	    }
165	
166	    public void setAddressLine2(String addressLine2) {
167	        this.addressLine2 = addressLine2;
168	    }
169	
170	    public String getCity() {
171	        return this.city;
172	    }
173	
174	    public void setCity(String city) {
175	        this.city = city;
176	    }
177	
178	    public String getTelephone() {
179	        return this.telephone;
180	    }
181	
182	    public void setTelephone(String telephone) {
183	        this.telephone = telephone;
184	    }
185	
186	    /**
187	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
188	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
189	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
190	     * persisted.
191	     */
192	    public String getTelephoneDisplay() {
193	        return E164PhoneNumber.toDisplay(this.telephone);
194	    }
195	
196	    public String getEmail() {
197	        return this.email;
198	    }
199	
200	    public void setEmail(String email) {
201	        this.email = email;
202	    }
203	
204	    /**
205	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
206	     * against the city's region and then stored verbatim. Optional, so may be null.
207	     */
208	    public String getPostcode() {
209	        return this.postcode;
210	    }
211	
212	    public void setPostcode(String postcode) {
213	        this.postcode = postcode;
214	    }
215	
216	    public LocalDate getRegistrationDate() {
217	        return this.registrationDate;
218	    }
219	
220	    public void setRegistrationDate(LocalDate registrationDate) {
221	        this.registrationDate = registrationDate;
222	    }
223	
224	    /**
225	     * The owner's date of birth. Optional, so may be null.
226	     */
227	    public LocalDate getBirthDate() {
228	        return this.birthDate;
229	    }
230	
231	    public void setBirthDate(LocalDate birthDate) {
232	        this.birthDate = birthDate;
233	    }
234	
235	    /**
236	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
237	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
238	     * birth date against the registration date. Null when no birth date is recorded.
239	     * Derived from stored state, never persisted.
240	     */
241	    public String getAgeBand() {
242	        if (this.birthDate == null || this.registrationDate == null) {
243	            return null;
244	        }
245	        return AgeBand.of(this.birthDate, this.registrationDate);
246	    }
247	
248	    public String getCustomerCode() {
249	        return this.customerCode;
250	    }
251	
252	    public void setCustomerCode(String customerCode) {
253	        this.customerCode = customerCode;
254	    }
255	
256	    /**
257	     * The stable identifier of the household this owner belongs to: the first twelve hex
258	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
259	     * sharing a last name and postcode resolves to the same value. Null when the owner has
260	     * no postcode. Assigned at creation.
261	     */
262	    public String getHouseholdId() {
263	        return this.householdId;
264	    }
265	
266	    public void setHouseholdId(String householdId) {
267	        this.householdId = householdId;
268	    }
269	
270	    public Integer getNamesakeCount() {
271	        return this.namesakeCount;
272	    }
273	
274	    public void setNamesakeCount(Integer namesakeCount) {
275	        this.namesakeCount = namesakeCount;
276	    }
277	
278	    public Integer getHouseholdSize() {
279	        return this.householdSize;
280	    }
281	
282	    public void setHouseholdSize(Integer householdSize) {
283	        this.householdSize = householdSize;
284	    }
285	
286	    public String getMembershipNumber() {
287	        return this.membershipNumber;
288	    }
289	
290	    public void setMembershipNumber(String membershipNumber) {
291	        this.membershipNumber = membershipNumber;
292	    }
293	
294	    /**
295	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: at
296	     * creation a new owner's level cannot exceed one above the highest level then held by an
297	     * existing member of its household (same last name and postcode). Null when no cap
298	     * applies, i.e. the household had no existing members. Captured at creation.
299	     */
300	    public Integer getMembershipLevelCap() {
301	        return this.membershipLevelCap;
302	    }
303	
304	    public void setMembershipLevelCap(Integer membershipLevelCap) {
305	        this.membershipLevelCap = membershipLevelCap;
306	    }
307	
308	    /**
309	     * Whether this owner was created as part of a bulk signup: {@code true} when more
310	     * than 80 owners had already been registered on this owner's registration date at
311	     * the moment it was created, {@code false} otherwise. Captured at creation.
312	     */
313	    public boolean isBulkSignupWarning() {
314	        return this.bulkSignupWarning;
315	    }
316	
317	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
318	        this.bulkSignupWarning = bulkSignupWarning;
319	    }
320	
321	    /**
322	     * Whether this owner resembles an existing one: {@code true} when, at creation, it shared
323	     * an existing owner's postcode and a phonetically-equal last name ({@link Soundex Soundex})
324	     * yet differed in {@link #getIdentityKey() identity key} and was not a declared household
325	     * member, {@code false} otherwise. A declared member (created with {@code sharesHousehold})
326	     * is a genuine member, not a suspected duplicate. When true, {@link #getPossibleDuplicateOf()}
327	     * holds that owner's id. Captured at creation.
328	     */
329	    public boolean isPossibleDuplicate() {
330	        return this.possibleDuplicate;
331	    }
332	
333	    public void setPossibleDuplicate(boolean possibleDuplicate) {
334	        this.possibleDuplicate = possibleDuplicate;
335	    }
336	
337	    /**
338	     * The id of the existing owner this owner possibly duplicates (same postcode and a
339	     * phonetically-equal last name but a different {@link #getIdentityKey() identity key}), or
340	     * null when it is not a possible duplicate. Captured at creation.
341	     */
342	    public Integer getPossibleDuplicateOf() {
343	        return this.possibleDuplicateOf;
344	    }
345	
346	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
347	        this.possibleDuplicateOf = possibleDuplicateOf;
348	    }
349	
350	    /**
351	     * Whether this owner has been soft-deleted: {@code true} once a {@code DELETE} has
352	     * flagged the record (which is retained rather than removed), {@code false} for a live
353	     * owner. A newly created owner is not deleted. A deleted owner is still returned by
354	     * {@code GET}, but is ignored by the create endpoint's duplicate and identity checks.
355	     */
356	    public boolean isDeleted() {
357	        return this.deleted;
358	    }
359	
360	    public void setDeleted(boolean deleted) {
361	        this.deleted = deleted;
362	    }
363	
364	    /**
365	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
366	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
367	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
368	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
369	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
370	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
371	     * region is derived directly from the stored postcode and city. Derived from stored
372	     * state, never persisted.
373	     */
374	    public String getLocality() {
375	        String region = CustomerCode.regionOf(this.customerCode);
376	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
377	    }
378	
379	    /**
380	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
381	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
382	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
383	     * has no known timezone. Derived from stored state, never persisted.
384	     */
385	    public String getTimezone() {
386	        return RegionTimezone.forRegion(getLocality());
387	    }
388	
389	    /**
390	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
391	     * has an email address, gains 1 when this owner had no namesakes at creation
392	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
393	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
394	     * A newly created owner has zero tenure, so it never earns those points at creation.
395	     * Derived from stored state, never persisted.
396	     */
397	    public int getMembershipPoints() {
398	        int points = 0;
399	        if (hasEmail()) {
400	            points += 2;
401	        }
402	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
403	            points += 1;
404	        }
405	        if (this.householdSize != null && this.householdSize >= 3) {
406	            points += 2;
407	        }
408	        if (getTenureFiscalYears() >= 1) {
409	            points += 3;
410	        }
411	        return points;
412	    }
413	
414	    /**
415	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
416	     * identified by its ending calendar year) of the {@code registrationDate}, or
417	     * {@code null} when no registration date is recorded. Derived from stored state, never
418	     * persisted.
419	     */
420	    public String getFiscalYear() {
421	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
422	    }
423	
424	    /**
425	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
426	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then capped at
427	     * the {@link #getMembershipLevelCap() membership level cap} when one applies. Derived from
428	     * stored state, never persisted.
429	     */
430	    public int getMembershipLevel() {
431	        int level = uncappedMembershipLevel();
432	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
433	    }
434	
435	    private int uncappedMembershipLevel() {
436	        int points = getMembershipPoints();
437	        if (points <= 1) {
438	            return 1;
439	        }
440	        if (points <= 3) {
441	            return 2;
442	        }
443	        if (points <= 5) {
444	            return 3;
445	        }
446	        return 4;
447	    }
448	
449	    /**
450	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
451	     * starting 1 July) between the {@code registrationDate} and the current server date, or
452	     * 0 when no registration date is recorded. Never negative in practice, since a future
453	     * registration date is rejected at creation.
454	     */
455	    private int getTenureFiscalYears() {
456	        if (this.registrationDate == null) {
457	            return 0;
458	        }
459	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
460	    }
461	
462	    /**
463	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
464	     * the {@code customerCode}. Derived from stored state, never persisted.
465	     */
466	    public int getCheckDigit() {
467	        return LuhnCheckDigit.of(this.customerCode);
468	    }
469	
470	    /**
471	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
472	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
473	     */
474	    public String getContactPreference() {
475	        return hasEmail() ? "EMAIL" : "PHONE";
476	    }
477	
478	    /**
479	     * The owner's identity key: the 64-character lower-case SHA-256 hex of the normalized
480	     * telephone, the lower-cased email (or empty when absent) and the {@link Soundex Soundex}
481	     * code of the last name, joined by {@code '|'}. Two owners collide on this key only when
482	     * they share a telephone, an email and a phonetically-equal surname, so it is the single
483	     * fingerprint the create endpoint's duplicate check keys off. Derived from stored state,
484	     * never persisted.
485	     */
486	    public String getIdentityKey() {
487	        String telephonePart = this.telephone == null ? "" : this.telephone;
488	        String emailPart = hasEmail() ? this.email.toLowerCase(Locale.ROOT) : "";
489	        String namePart = Soundex.of(getLastName());
490	        return Sha256.lowerHex(telephonePart + "|" + emailPart + "|" + namePart);
491	    }
492	
493	    private boolean hasEmail() {
494	        return this.email != null && !this.email.isEmpty();
495	    }
496	
497	    protected Set<Pet> getPetsInternal() {
498	        if (this.pets == null) {
499	            this.pets = new HashSet<>();
500	        }
501	        return this.pets;
502	    }
503	
504	    protected void setPetsInternal(Set<Pet> pets) {
505	        this.pets = pets;
506	    }
507	
508	    public List<Pet> getPets() {
509	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
510	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
511	        return Collections.unmodifiableList(sortedPets);
512	    }
513	
514	    public void setPets(List<Pet> pets) {
515	        this.pets = new HashSet<>(pets);
516	    }
517	
518	    public void addPet(Pet pet) {
519	        getPetsInternal().add(pet);
520	        pet.setOwner(this);
521	    }
522	
523	    /**
524	     * Return the Pet with the given name, or null if none found for this Owner.
525	     *
526	     * @param name to test
527	     * @return true if pet name is already in use
528	     */
529	    public Pet getPet(String name) {
530	        return getPet(name, false);
531	    }
532	
533	    /**
534	     * Return the Pet with the given name, or null if none found for this Owner.
535	     *
536	     * @param name to test
537	     * @return true if pet name is already in use
538	     */
539	    public Pet getPet(String name, boolean ignoreNew) {
540	        name = name.toLowerCase();
541	        for (Pet pet : getPetsInternal()) {
542	            if (!ignoreNew || !pet.isNew()) {
543	                String compName = pet.getName();
544	                compName = compName.toLowerCase();
545	                if (compName.equals(name)) {
546	                    return pet;
547	                }
548	            }
549	        }
550	        return null;
551	    }
552	
553	    public Pet getPet(Integer petId) {
554	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
555	    }
556	
557	    @Override
558	    public String toString() {
559	        return new ToStringCreator(this)
560	
561	            .append("id", this.getId())
562	            .append("new", this.isNew())
563	            .append("lastName", this.getLastName())
564	            .append("firstName", this.getFirstName())
565	            .append("address", this.address)
566	            .append("city", this.city)
567	            .append("telephone", this.telephone)
568	            .toString();
569	    }
570	}
